def process(miami_florida_state, miami_metro_data) -> pd.DataFrame:
    florida_reports = miami_florida_state['Reports'].values[0]
    metro_reports = miami_metro_data['Reports'].values[0]

    is_consistent = florida_reports == metro_reports

    return pd.DataFrame({
        'Florida State Data': [florida_reports],
        'Metro Data': [metro_reports],
        'Consistent': [is_consistent]
    })
